use std::env;

const IV: [u32; 8] = [
    0x6A09E667, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A,
    0x510E527F, 0x9B05688C, 0x1F83D9AB, 0x5BE0CD19
];
const MSG_SCHEDULE: [usize; 16] = [2, 6, 3, 10, 7, 0, 4, 13, 1, 11, 12, 5, 9, 14, 15, 8];

fn rotr32(x: u32, y: u32) -> u32 {
    x.rotate_right(y)
}

fn g(v: &mut [u32; 16], a: usize, b: usize, c: usize, d: usize, x: u32, y: u32) {
    v[a] = v[a].wrapping_add(v[b]).wrapping_add(x); v[d] = rotr32(v[d] ^ v[a], 16);
    v[c] = v[c].wrapping_add(v[d]); v[b] = rotr32(v[b] ^ v[c], 12);
    v[a] = v[a].wrapping_add(v[b]).wrapping_add(y); v[d] = rotr32(v[d] ^ v[a], 8);
    v[c] = v[c].wrapping_add(v[d]); v[b] = rotr32(v[b] ^ v[c], 7);
}

fn round_fn(v: &mut [u32; 16], m: &[u32; 16]) {
    g(v, 0, 4, 8, 12, m[0], m[1]); g(v, 1, 5, 9, 13, m[2], m[3]);
    g(v, 2, 6, 10, 14, m[4], m[5]); g(v, 3, 7, 11, 15, m[6], m[7]);
    g(v, 0, 5, 10, 15, m[8], m[9]); g(v, 1, 6, 11, 12, m[10], m[11]);
    g(v, 2, 7, 8, 13, m[12], m[13]); g(v, 3, 4, 9, 14, m[14], m[15]);
}

fn compress(cv: &[u32; 8], block: &[u8], counter: u64, block_len: u32, flags: u32) -> [u32; 16] {
    let mut v = [0u32; 16];
    v[0..8].copy_from_slice(cv);
    v[8..12].copy_from_slice(&IV[0..4]);
    v[12] = counter as u32;
    v[13] = (counter >> 32) as u32;
    v[14] = block_len;
    v[15] = flags;

    let mut m = [0u32; 16];
    for i in 0..16 {
        let mut b = [0u8; 4];
        if i * 4 < block.len() {
            let len = std::cmp::min(4, block.len() - i * 4);
            b[..len].copy_from_slice(&block[i * 4..i * 4 + len]);
        }
        m[i] = u32::from_le_bytes(b);
    }

    for _ in 0..7 {
        round_fn(&mut v, &m);
        let mut next_m = [0u32; 16];
        for j in 0..16 {
            next_m[j] = m[MSG_SCHEDULE[j]];
        }
        m = next_m;
    }
    v
}

fn compress_chunk(cv: &[u32; 8], block: &[u8], counter: u64, block_len: u32, flags: u32) -> [u32; 8] {
    let v = compress(cv, block, counter, block_len, flags);
    let mut out = [0u32; 8];
    for i in 0..8 {
        out[i] = v[i] ^ v[i+8];
    }
    out
}

fn main() {
    let out = compress_chunk(&IV, b"hello", 0, 5, 1 | 2 | 8);
    for word in out {
        print!("{:08x}", word.to_be());
    }
    println!();
}
EOF
