    v[8..12].copy_from_slice(&IV[0..4]);
    v[12] = counter as u32;
    v[13] = (counter >> 32) as u32;
    v[14] = block_len;
    v[15] = flags;

    let mut m = [0u32; 16];
    for i in 0..16 {
        m[i] = u32::from_le_bytes([
            block[i*4], block[i*4+1], block[i*4+2], block[i*4+3]
        ]);
    }

    for _ in 0..7 {
        round_fn(&mut v, &m);
        let mut next_m = [0u32; 16];
        for j in 0..16 { next_m[j] = m[MSG_SCHEDULE[j]]; }
        m = next_m;
    }
    v
}

fn compress_block(cv: &[u32; 8], block: &[u8; 64], counter: u64, block_len: u32, flags: u32) -> [u32; 8] {
    let v = compress(cv, block, counter, block_len, flags);
    let mut out = [0u32; 8];
    for i in 0..8 { out[i] = v[i] ^ v[i+8]; }
    out
}

#[derive(Clone)]
struct RootNode {
    cv: [u32; 8],
    block: [u8; 64],
    block_len: u32,
    flags: u32,
}

impl RootNode {
    fn xof(&self, t: u64) -> [u8; 64] {
        let v = compress(&self.cv, &self.block, t, self.block_len, self.flags);
        let mut out = [0u8; 64];
        for i in 0..8 {
            out[i*4..i*4+4].copy_from_slice(&(v[i] ^ v[i+8]).to_le_bytes());
        }
        for i in 0..8 {
            out[32+i*4..32+i*4+4].copy_from_slice(&(v[i+8] ^ self.cv[i]).to_le_bytes());
        }
        out
    }
}

struct Hasher {
    iv: [u32; 8],
    flags: u32,
    counter: u64,
    buf: [u8; 1024],
    buf_len: usize,
    cv_stack: Vec<([u32; 8], u8)>,
}

impl Hasher {
    fn new(key: Option<&[u32; 8]>, flags: u32) -> Self {
        Self {
            iv: if let Some(k) = key { *k } else { IV },
            flags: flags | if key.is_some() { 16 } else { 0 },
            counter: 0,
            buf: [0; 1024],
            buf_len: 0,
            cv_stack: Vec::new(),
        }
    }

    fn push_cv(&mut self, mut cv: [u32; 8]) {
        let mut depth = 0;
        while let Some(&(prev_cv, prev_depth)) = self.cv_stack.last() {
            if prev_depth == depth {
                self.cv_stack.pop();
                let mut block = [0u8; 64];
                for i in 0..8 {
                    block[i*4..i*4+4].copy_from_slice(&prev_cv[i].to_le_bytes());
                    block[32+i*4..32+i*4+4].copy_from_slice(&cv[i].to_le_bytes());
                }
                cv = compress_block(&self.iv, &block, 0, 64, 4 | self.flags);
                depth += 1;
            } else {
                break;
            }
        }
        self.cv_stack.push((cv, depth));
    }

    fn update(&mut self, mut data: &[u8]) {
        while !data.is_empty() {
            if self.buf_len == 1024 {
                let mut cv = self.iv;
                for i in 0..16 {
                    let mut block = [0u8; 64];
                    block.copy_from_slice(&self.buf[i*64..i*64+64]);
                    let mut b_flags = self.flags;
                    if i == 0 { b_flags |= 1; }
                    if i == 15 { b_flags |= 2; }
                    cv = compress_block(&cv, &block, self.counter, 64, b_flags);
                }
                self.push_cv(cv);
                self.buf_len = 0;
                self.counter += 1;
            }
            let take = cmp::min(1024 - self.buf_len, data.len());
            self.buf[self.buf_len..self.buf_len+take].copy_from_slice(&data[..take]);
            self.buf_len += take;
            data = &data[take..];
        }
    }

    fn finalize(&self) -> RootNode {
        let num_blocks = cmp::max(1, (self.buf_len + 63) / 64);
        let mut cv = self.iv;
        for i in 0..num_blocks-1 {
            let mut block = [0u8; 64];
            block.copy_from_slice(&self.buf[i*64..i*64+64]);
            let mut b_flags = self.flags;
            if i == 0 { b_flags |= 1; }
            cv = compress_block(&cv, &block, self.counter, 64, b_flags);
        }
        let last_idx = num_blocks - 1;
        let mut block = [0u8; 64];
        let rem = self.buf_len - last_idx * 64;
        block[..rem].copy_from_slice(&self.buf[last_idx*64..last_idx*64+rem]);

        let mut b_flags = self.flags;
        if last_idx == 0 { b_flags |= 1; }
        b_flags |= 2;

        if self.cv_stack.is_empty() {
            b_flags |= 8;
            return RootNode {
                cv, block, block_len: rem as u32, flags: b_flags
            };
        }

        cv = compress_block(&cv, &block, self.counter, rem as u32, b_flags);

        for (i, &(prev_cv, _)) in self.cv_stack.iter().rev().enumerate() {
            let is_root = i == self.cv_stack.len() - 1;
            let mut pblock = [0u8; 64];
            for j in 0..8 {
                pblock[j*4..j*4+4].copy_from_slice(&prev_cv[j].to_le_bytes());
                pblock[32+j*4..32+j*4+4].copy_from_slice(&cv[j].to_le_bytes());
            }
            let mut p_flags = 4 | self.flags;
            if is_root {
                p_flags |= 8;
                return RootNode {
                    cv: self.iv, block: pblock, block_len: 64, flags: p_flags
                };
            } else {
                cv = compress_block(&self.iv, &pblock, 0, 64, p_flags);
            }
        }
        unreachable!()
    }
}

