fn compute_hash(mut reader: impl Read, key: Option<[u32; 8]>, derive_key: Option<&str>) -> io::Result<RootNode> {
    let mut h = if let Some(ref ctx) = derive_key {
        let mut h_ctx = Hasher::new(None, 32); // DERIVE_KEY_CONTEXT
        h_ctx.update(ctx.as_bytes());
        let root_ctx = h_ctx.finalize();
        let mut key_ctx = [0u32; 8];
        let xof = root_ctx.xof(0);
        for i in 0..8 {
            let mut b = [0u8; 4];
            b.copy_from_slice(&xof[i*4..i*4+4]);
            key_ctx[i] = u32::from_le_bytes(b);
        }
        Hasher::new(Some(&key_ctx), 64) // DERIVE_KEY_MATERIAL
    } else {
        Hasher::new(key.as_ref(), 0)
    };

    let mut buf = [0u8; 65536];
    loop {
        let n = reader.read(&mut buf)?;
        if n == 0 { break; }
        h.update(&buf[..n]);
    }
    Ok(h.finalize())
}

